import json, os
def transform(grid):
    h,w=len(grid),len(grid[0])
    best=None
    for name in DIRS:
        ph=PHASE[name]
        cons={}
        for r in range(h):
            for c in range(w):
                v=grid[r][c]
                if v: cons.setdefault(ph(r,c),set()).add(v)
        for p in range(1,31):
            sq={}; good=True
            for phv,vs in cons.items():
                i=phv%p
                if len(vs)>1 or (i in sq and sq[i]!=next(iter(vs))): good=False;break
                sq[i]=next(iter(vs))
            if good and len(sq)==p:
                if best is None or p<best[0]: best=(p,name,sq)
                break
    p,name,sq=best
    ph=PHASE[name]
    return [[sq[ph(r,c)%p] for c in range(w)] for r in range(h)]

