PHASE = {'v': lambda r, c: c, 'h': lambda r, c: r, 'dr': lambda r, c: c - r, 'dl': lambda r, c: c + r}

def stripe_fill(grid, max_period=30):
    """Fill the whole grid with the periodic stripe pattern implied by its colored lines: find the line direction, then the smallest period whose phase classes are fully and consistently colored, and color every cell by its phase."""
    h, w = len(grid), len(grid[0])
    best = None
    for name in DIRS:
        ph = PHASE[name]
        cons = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    cons.setdefault(ph(r, c), set()).add(v)
        for p in range(1, max_period + 1):
            seq = {}
            good = True
            for phv, vs in cons.items():
                i = phv % p
                if len(vs) > 1 or (i in seq and seq[i] != next(iter(vs))):
                    good = False
                    break
                seq[i] = next(iter(vs))
            if good and len(seq) == p:
                if best is None or p < best[0]:
                    best = (p, name, dict(seq))
                break
    p, name, seq = best
    ph = PHASE[name]
    return [[seq[ph(r, c) % p] for c in range(w)] for r in range(h)]
'''
